// Toggle between day and night palettes (pure CSS variables do the rest)
var btn = document.getElementById('toggle');
btn.addEventListener('click', function () {
  document.body.classList.toggle('night');
  var night = document.body.classList.contains('night');
  btn.innerHTML = night ? '&#9728;&#65039; Day mode' : '&#127769; Night mode';
});

var cv = document.getElementById('game'), ctx = cv.getContext('2d');
var score = 0, timeLeft = 30, target = null, timer = null, playing = false;

function spawn() {
  var r = 18 + Math.random() * 22;
  target = { x: r + Math.random() * (cv.width - 2 * r), y: r + Math.random() * (cv.height - 2 * r), r: r };
}
function draw() {
  ctx.clearRect(0, 0, cv.width, cv.height);
  if (!target) return;
  ctx.beginPath(); ctx.arc(target.x, target.y, target.r, 0, 7); ctx.fillStyle = '#ff4d5e'; ctx.fill();
  ctx.beginPath(); ctx.arc(target.x, target.y, target.r * 0.55, 0, 7); ctx.fillStyle = '#fff'; ctx.fill();
  ctx.beginPath(); ctx.arc(target.x, target.y, target.r * 0.25, 0, 7); ctx.fillStyle = '#ff4d5e'; ctx.fill();
}
cv.addEventListener('click', function (e) {
  if (!playing || !target) return;
  var r = cv.getBoundingClientRect();
  var x = (e.clientX - r.left) * (cv.width / r.width);
  var y = (e.clientY - r.top) * (cv.height / r.height);
  if (Math.hypot(x - target.x, y - target.y) <= target.r) {
    score++;
    document.getElementById('score').textContent = score;
    spawn(); draw();
  }
});
document.getElementById('start').addEventListener('click', function () {
  score = 0; timeLeft = 30; playing = true;
  document.getElementById('score').textContent = '0';
  document.getElementById('time').textContent = '30';
  document.getElementById('gmsg').textContent = 'Go!';
  spawn(); draw();
  clearInterval(timer);
  timer = setInterval(function () {
    timeLeft--;
    document.getElementById('time').textContent = timeLeft;
    if (timeLeft <= 0) {
      clearInterval(timer); playing = false; target = null; draw();
      document.getElementById('gmsg').textContent = 'Time up! Final score: ' + score + '. Hit Start to play again.';
    }
  }, 1000);
});
draw();

