var KEY = 'nitroide-todo-v1';
var todos = [];
try { todos = JSON.parse(localStorage.getItem(KEY)) || []; } catch (e) { todos = []; }

var list = document.getElementById('tlist');
var input = document.getElementById('tinput');
var countEl = document.getElementById('tcount');

function esc(s) {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function save() { localStorage.setItem(KEY, JSON.stringify(todos)); }
function render() {
  list.innerHTML = '';
  if (!todos.length) {
    list.innerHTML = '<li class="t-empty">Nothing here yet &mdash; add your first task.</li>';
  }
  todos.forEach(function (t, i) {
    var li = document.createElement('li');
    if (t.done) li.className = 'done';
    li.innerHTML = '<input type="checkbox"' + (t.done ? ' checked' : '') + ' data-i="' + i + '">' +
      '<span>' + esc(t.text) + '</span>' +
      '<button class="del" data-i="' + i + '" aria-label="Delete">&times;</button>';
    list.appendChild(li);
  });
  var left = todos.filter(function (t) { return !t.done; }).length;
  countEl.textContent = left + ' task' + (left === 1 ? '' : 's') + ' left';
}
list.addEventListener('click', function (e) {
  var i = e.target.getAttribute('data-i');
  if (i === null) return;
  i = +i;
  if (e.target.classList.contains('del')) todos.splice(i, 1);
  else if (e.target.type === 'checkbox') todos[i].done = e.target.checked;
  save(); render();
});
document.getElementById('tform').addEventListener('submit', function (e) {
  e.preventDefault();
  var text = input.value.trim();
  if (!text) return;
  todos.unshift({ text: text, done: false });
  input.value = '';
  save(); render();
});
document.getElementById('tclear').addEventListener('click', function () {
  todos = todos.filter(function (t) { return !t.done; });
  save(); render();
});
render();

