var hh = document.getElementById('hh');
var mh = document.getElementById('mh');
var sh = document.getElementById('sh');
var dig = document.getElementById('dig');
var dateEl = document.getElementById('date');

function pad(n) { return String(n).padStart(2, '0'); }
function tick() {
  var now = new Date();
  var s = now.getSeconds() + now.getMilliseconds() / 1000;
  var m = now.getMinutes() + s / 60;
  var h = (now.getHours() % 12) + m / 60;
  sh.style.transform = 'rotate(' + (s * 6) + 'deg)';
  mh.style.transform = 'rotate(' + (m * 6) + 'deg)';
  hh.style.transform = 'rotate(' + (h * 30) + 'deg)';
  dig.textContent = pad(now.getHours()) + ':' + pad(now.getMinutes()) + ':' + pad(now.getSeconds());
  dateEl.textContent = now.toLocaleDateString(undefined, { weekday: 'long', month: 'long', day: 'numeric' });
  requestAnimationFrame(tick);
}
tick();

var c1 = document.getElementById('c1');
var c2 = document.getElementById('c2');
var ang = document.getElementById('ang');
var angv = document.getElementById('angv');
var preview = document.getElementById('preview');
var code = document.getElementById('code');
var copyBtn = document.getElementById('copy');

var presets = [
  ['#6ee7ff', '#a855f7'], ['#f472b6', '#facc15'], ['#34d399', '#3b82f6'],
  ['#fb7185', '#7c3aed'], ['#fde68a', '#f97316'], ['#22d3ee', '#16a34a']
];
var presetBox = document.getElementById('presets');
presets.forEach(function (p) {
  var b = document.createElement('button');
  b.style.background = 'linear-gradient(135deg,' + p[0] + ',' + p[1] + ')';
  b.title = p[0] + ' / ' + p[1];
  b.addEventListener('click', function () { c1.value = p[0]; c2.value = p[1]; update(); });
  presetBox.appendChild(b);
});

function update() {
  var css = 'linear-gradient(' + ang.value + 'deg, ' + c1.value + ', ' + c2.value + ')';
  preview.style.background = css;
  code.textContent = 'background: ' + css + ';';
  angv.innerHTML = ang.value + '&deg;';
}
[c1, c2, ang].forEach(function (el) { el.addEventListener('input', update); });

copyBtn.addEventListener('click', function () {
  var text = code.textContent;
  function done() { copyBtn.textContent = 'Copied!'; setTimeout(function () { copyBtn.textContent = 'Copy CSS'; }, 1500); }
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(done, function () { fallback(); });
  } else { fallback(); }
  function fallback() {
    var ta = document.createElement('textarea');
    ta.value = text; document.body.appendChild(ta); ta.select();
    try { document.execCommand('copy'); } catch (e) {}
    document.body.removeChild(ta); done();
  }
});
update();

