var input = document.getElementById('mdin');
var out = document.getElementById('mdout');

function esc(s) {
  return s.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function inline(s) {
  s = esc(s);
  s = s.replace(/`([^`]+)`/g, '<code>$1</code>');
  s = s.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  s = s.replace(/\*([^*]+)\*/g, '<em>$1</em>');
  s = s.replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>');
  return s;
}
function render() {
  var lines = input.value.split('\n');
  var html = '', inList = false;
  lines.forEach(function (line) {
    if (/^###\s/.test(line)) html += '<h3>' + inline(line.slice(4)) + '</h3>';
    else if (/^##\s/.test(line)) html += '<h2>' + inline(line.slice(3)) + '</h2>';
    else if (/^#\s/.test(line)) html += '<h1>' + inline(line.slice(2)) + '</h1>';
    else if (/^>\s/.test(line)) html += '<blockquote>' + inline(line.slice(2)) + '</blockquote>';
    else if (/^---+\s*$/.test(line)) html += '<hr>';
    else if (/^-\s/.test(line)) {
      if (!inList) { html += '<ul>'; inList = true; }
      html += '<li>' + inline(line.slice(2)) + '</li>';
    } else {
      if (inList) { html += '</ul>'; inList = false; }
      if (line.trim()) html += '<p>' + inline(line) + '</p>';
    }
  });
  if (inList) html += '</ul>';
  out.innerHTML = html;
}
input.addEventListener('input', render);
render();

