var KEY = 'nitroide-countdown-v1';
var state = null;
try { state = JSON.parse(localStorage.getItem(KEY)); } catch (e) { state = null; }

var nameEl = document.getElementById('cdName');
var daysEl = document.getElementById('cdDays');
var hoursEl = document.getElementById('cdHours');
var minsEl = document.getElementById('cdMins');
var secsEl = document.getElementById('cdSecs');
var msgEl = document.getElementById('cdMsg');
var form = document.getElementById('cdForm');
var eventInput = document.getElementById('cdEvent');
var dateInput = document.getElementById('cdDate');
var resetBtn = document.getElementById('cdReset');

function pad(n) { return String(n).padStart(2, '0'); }
function save() { localStorage.setItem(KEY, JSON.stringify(state)); }

function tick() {
  if (!state || !state.target) {
    daysEl.textContent = hoursEl.textContent = minsEl.textContent = secsEl.textContent = '00';
    msgEl.textContent = 'Set a date below to start the countdown.';
    return;
  }
  var diff = new Date(state.target).getTime() - Date.now();
  if (diff <= 0) {
    daysEl.textContent = hoursEl.textContent = minsEl.textContent = secsEl.textContent = '00';
    msgEl.textContent = '🎉 ' + (state.name || 'Your event') + ' is happening now!';
    return;
  }
  daysEl.textContent = pad(Math.floor(diff / 86400000));
  hoursEl.textContent = pad(Math.floor(diff / 3600000) % 24);
  minsEl.textContent = pad(Math.floor(diff / 60000) % 60);
  secsEl.textContent = pad(Math.floor(diff / 1000) % 60);
  msgEl.textContent = '';
}

form.addEventListener('submit', function (e) {
  e.preventDefault();
  if (!dateInput.value) return;
  state = { name: eventInput.value.trim() || 'My Event', target: dateInput.value };
  nameEl.textContent = state.name;
  resetBtn.hidden = false;
  save();
  tick();
});

resetBtn.addEventListener('click', function () {
  state = null;
  try { localStorage.removeItem(KEY); } catch (e) {}
  nameEl.textContent = 'My Event';
  eventInput.value = '';
  dateInput.value = '';
  resetBtn.hidden = true;
  tick();
});

// Restore a previously saved countdown
if (state && state.target) {
  nameEl.textContent = state.name || 'My Event';
  eventInput.value = state.name || '';
  dateInput.value = state.target;
  resetBtn.hidden = false;
}
setInterval(tick, 1000);
tick();

