// Staggered entrance: reveal each section with a small delay
var wrap = document.querySelector('.bio-wrap');
Array.prototype.forEach.call(wrap.children, function (el, i) {
  el.style.transitionDelay = (i * 0.08) + 's';
});
requestAnimationFrame(function () { wrap.classList.add('loaded'); });

// Share button: native share sheet if available, clipboard fallback otherwise
var shareBtn = document.getElementById('bioShare');
var msg = document.getElementById('bioMsg');
shareBtn.addEventListener('click', function () {
  var url = window.location.href;
  function done(text) {
    msg.textContent = text;
    setTimeout(function () { msg.textContent = ''; }, 2200);
  }
  if (navigator.share) {
    navigator.share({ title: document.title, url: url }).catch(function () {});
  } else if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(url).then(function () { done('Link copied to clipboard!'); }, function () { done('Copy this URL: ' + url); });
  } else {
    var ta = document.createElement('textarea');
    ta.value = url; document.body.appendChild(ta); ta.select();
    try { document.execCommand('copy'); done('Link copied to clipboard!'); }
    catch (e) { done('Copy this URL: ' + url); }
    document.body.removeChild(ta);
  }
});
